definition.raw:
We define the \emph{defect}\, operator $ D_m(t) $ of $ S_m(t) $ by
\begin{equation*}
D_m(t) = \sca\,\Opgen\,S_m(t) - S_m'(t) \in \mathbb C^{n \times n}.

theorem.raw:
\label{theorem:upperboundexp}

\noindent
For the nonexpansive case the error $ L_m(t)v $ of the Krylov approximation~\eqref{Smv}
to $ E(t)v $ satisfies
\begin{equation} \label{asyerrest}
\| L_m(t)v \|_2 \leq \tau_{m+1,m}\gamma_m\,\frac{t^{m}}{m!}
\end{equation}
with $ \tau_{m+1,m} $ from~\eqref{krylovidentity} and
$ \gamma_m $ from~\eqref{gammam}.

\label{theorem:upperboundphi}
The error of the Krylov approximation~\eqref{kry-phi}
to $ \phif_p(\sca\,t \Opgen)v $ with $ p \geq 0 $ satisfies
\begin{subequations}
\begin{equation}\label{leadingtermphij}
L^p_m(t)v = \tau_{m+1,m}\,\gamma_m \frac{(\sca\, t)^m}{(m+p)!} \, v_{m+1} + \mathcal{O}(t^{m+1}).
\end{equation}
Furthermore, \tjnew{in the nonexpansive case} its norm is bounded by
\begin{equation}\label{eresphij}
\|L^p_m(t)v \|_2  \leq   \tau_{m+1,m}\,\gamma_m\,\frac{t^{m}}{(m+p)!},
\end{equation}
\end{subequations}
and this bound is asymptotically correct for $ t \to 0 $.

\label{theorem:asymerrorpricorrected}
The error of the corrected Krylov approximation~\eqref{generalizeerrornotation2}
to $ \phif_p(\sca\,t \Opgen)v $ with $ p \geq 0 $ satisfies
\begin{subequations}
\begin{equation}\label{leadingtermphijcor}
L^{p,+}_m(t)v  = \tau_{m+1,m}\,\gamma_m \frac{(\sca\, t)^{m+1}}{(m+p+1)!} \, \Opgen v_{m+1} + \mathcal{O}(t^{m+2}).
\end{equation}
Furthermore, \tjnew{in the nonexpansive case} its norm is bounded by
\begin{equation}\label{eresphijcor}
\|L^{p,+}_m(t)v\|_2 \leq    \|\Opgen v_{m+1}\|_2\, \tau_{m+1,m}\,\gamma_m \frac{t^{m+1}}{(m+p+1)!},
\end{equation}
\end{subequations}
and this bound is asymptotically correct for $ t \to 0 $.

proposition.raw:
\label{prop:prop3}
\noindent
For any $ A \in \mathbb C^{\tjnew{n \times n}} $
the error $ L_m(t)v $ satisfies the asymptotic relation
\begin{equation} \label{asy-leading}
L_m(t)v = \tau_{m+1,m}\gamma_m\,\frac{(\sca\,t)^{m}}{m!}v_{m+1} + R_{m+1}(t),
\quad R_{m+1}(t) = {\mathcal{O}}(t^{m+1}),
\end{equation}
for $ t \to 0 $.

\label{prop:prop1}

\noindent
Let $T_m \in \mathbb C^{m\times m}$ be an upper Hessenberg matrix with eigenvalues $ \lambda_1,\ldots,\lambda_m $
and $ \text{spec}(\sca T_m) \subseteq \mathbb C_- $.
Then the function $ \delta_m(t) $ defined as in~\eqref{defdelta}, i.e.,
\begin{equation*}
\delta_m(t) = e_m^\ast\,{\rm e}^{\sca\,t\,T_m}e_1
            = \big( {\rm e}^{\sca\,t\,T_m} \big)_{m,1},
\end{equation*}
satisfies
\begin{equation}\label{deltam-repr}
\delta_m(t) =
\divdif{\lambda_1,\ldots,\lambda_m}{f_t} \gamma_m
\leq {\frac{t^{m-1}}{(m-1)!}\,\gamma_m,}
\end{equation}
with $ \gamma_m $ from~\eqref{gammam} and
where $\divdif{\lambda_1,\ldots,\lambda_m}{f_t}$ is
the {$ (m-1) $-th} divided difference over
$ \text{\rm spec}(T_m) $
of the function $ f_t $ defined in~\eqref{def:thetadd}.

\label{prop:prop4}

\noindent
The upper bound~\eqref{asyerrest} is asymptotically correct
for $ t \to 0 $, i.e.,
\begin{equation} \label{asyerrcorr}
\| L_m(t)v \|_2 = \tau_{m+1,m}\gamma_m\,\frac{t^m}{m!} + {\mathcal{O}}(t^{m+1}).
\end{equation}

{{\rm{see~\cite[Theorem 5.1]{saad92s}}}}\label{prop:saad92}
With the $\phif$-functions defined in~\eqref{defphi},
the error~\eqref{Lerror} can be represented in the form
\begin{align}\label{sumofsaad}
L_m(t)v =
 \tau_{m+1,m}\,\sca\,t
  \sum_{j=1}^{\infty} e_m^\ast\phif_{j}(\sca\,tT_m)\,e_1 (\sca\,t \Opgen)^{j-1}v_{m+1}.
\end{align}

{sidje98}}]\label{prop:generalSaadsum}
\begin{subequations}
The error of the Krylov approximation $L^p_m(t)v$, see~\eqref{generalizeerrornotation}, satisfies
\begin{equation}\label{generalizeerrorSaadsum1}
L^p_m(t)v = \tau_{m+1,m} \sca\,t \sum_{j=p+1}^{\infty} (e_m^\ast \phif_j(\sca\,t\,T_m) e_1) \,(\sca\,t\,\Opgen)^{j-p-1} v_{m+1}.
\end{equation}
The error of the corrected Krylov approximation $L^{p,+}_m(t)v$, see~\eqref{generalizeerrornotation2}, is given by
\begin{equation}\label{generalizeerrorSaadsum2}
L^{p,+}_m(t)v = \tau_{m+1,m} \sca\,t \sum_{j=p+2}^{\infty} (e_m^\ast \phif_j(\sca\,t\,T_m) e_1) \,(\sca\,t\,\Opgen)^{j-p-1} v_{m+1}.
\end{equation}
\end{subequations}

\label{upperboundphi}
\tjnew{For the nonexpansive case} with $\sca=1$ and \tjnew{a Hermitian} matrix $\Opgen$ we obtain
\begin{equation*}
|\delta_m(t)| = \delta_m(t) > 0 ~~~\text{for}~~t > 0.
\end{equation*}
This leads to the following upper bounds for the errors $L^p_m$ and $L^{p,+}_m$ with $p\geq 0$:
\begin{subequations}
\begin{equation}\label{hermitianphiestimate1}
\|L^p_m(t)v\|_2 \leq \tau_{m+1,m} \, t \, \underbrace{e_m^\ast \, \phif_{p+1}(tT_m) \, e_1}_{\geq\, 0}
\end{equation}
and
\begin{equation}\label{hermitianphiestimate2}
\|L^{p,+}_m(t)v\|_2 \leq \|\Opgen v_{m+1}\|_2 \,\tau_{m+1,m} \, t^2 \, \underbrace{e_m^\ast \, \phif_{p+2}(tT_m) \, e_1}_{\geq\, 0}.
\end{equation}
\end{subequations}

proof.raw:
Taylor expansion. Due to $ L_m(t)v = {\mathcal{O}}(t^m) $, \tjnew{see~\eqref{orderofDmLm},}
\begin{equation}\label{prop-3-proof}
\begin{aligned}
&L_m(t)v = E(t)v - S_m(t)v
= \frac{(\sca\,t)^m}{{m!}}(\Opgen^m v - V_m T_m^m\,e_1) + R_{m+1}(t),\\
&\text{with Taylor remainder}~~ R_{m+1}(t) = {\mathcal{O}}(t^{m+1}).
\end{aligned}
\end{equation}
Multiplying the
identity~\tjnew{{\eqref{HVTm}} (with $ j = m-1 $) by $ A $} and using~\eqref{krylovidentity} gives
\begin{align*}
\Opgen^m\,v
&= \Opgen\,V_m T_m^{m-1} e_1
 = (V_m T_m + \tau_{m+1,m}\,v_{m+1} e_m^\ast) T_m^{m-1} e_1 \\
&= V_m T_m^m\,e_1 + \tau_{m+1,m}\, (e_m^\ast\,T_m^{m-1} e_1)\,v_{m+1}
 = V_m T_m^m\,e_1 + \tau_{m+1,m} \gamma_m v_{m+1},
\end{align*}
whence~\eqref{prop-3-proof} simplifies to~\eqref{asy-leading}. \qed

We proceed from the Newton representation of the
interpolant $p_t(\lambda) $ from~\eqref{pt},
\begin{equation*}
p_t(\lambda) = \sum_{j=0}^{m-1}
               \divdif{\lambda_1,\ldots,\lambda_{j+1}}{f_t}\,\omega_j(\lambda),
\end{equation*}
with
$ \omega_j(\lambda) = (\lambda-\lambda_1) \cdots (\lambda-\lambda_{j}) $.

{From~\eqref{eTe} and by definition of $ \gamma_m $, 
it is obvious that the $ \omega_j $ satisfy}
\begin{equation*}
e_m^\ast\,\omega_j(T_m)\,e_1 =
\left\{\begin{array}{ll}
0,       & j=0,\ldots,m-2, \\
\gamma_m,& j=m-1.
\end{array}\right.
\end{equation*}
Together with~\eqref{pt} this shows that the identity claimed
in~\eqref{deltam-repr} is valid:
\begin{equation*}
\delta_m(t)
= e_m^\ast\,{\rm e}^{\sca\,t T_m}\,e_1
= e_m^\ast\,p_t(T_m) e_1
= \sum_{j=0}^{m-1} \divdif{\lambda_1,\ldots,\lambda_{j+1}}{f_t} e_m^\ast\,\omega_j(T_m)e_1
= \divdif{\lambda_1,\ldots,\lambda_m}{f_t} \gamma_m.
\end{equation*}
