\divdif{\lambda_1,\ldots,\lambda_m}{f_t} = \frac{D^{(m-1)} f_t(\xi)}{(m-1)!} = \frac{t^{m-1} {\rm e}^{t\xi}}{(m-1)!}~~~\text{for}~~\xi\in[\lambda_1,\lambda_m].
\end{equation}
Equation~\eqref{ddreal} shows $\divdif{\lambda_1,\ldots,\lambda_m}{f_t} > 0$ and with $\gamma_m > 0 $ we conclude
\begin{equation*}
\delta_m(t) > 0,~~~\text{and}~~~|\delta_m(t)|=\delta_m(t).
\end{equation*}
We continue with~\eqref{hermitianphiestimate1} in the case $p=0$:
\begin{equation*}
\|L_m(t)v\|_2\leq \tau_{m+1,m} \int_0^t |\delta_m(s)|\,\mathrm{d} s = \tau_{m+1,m} \int_0^t e_m^\ast\,{\rm e}^{sT_m} \,e_1 \,\mathrm{d} s = \tau_{m+1,m} t \, e_m^\ast \, \phif_1(tT_m) \, e_1.
\end{equation*}
For the case $p \geq 1$ we start analogously to Theorem~\ref{theorem:upperboundphi}.
Using definition~\eqref{defphiint} for the $\phif$-functions
and resorting to the case $p=0$ we find
\begin{align*}
\| L_m^p(t)v \|_2
&= \frac{1}{(p-1)!} \int_0^1 (1-\theta)^{p-1}  \|L_m(\theta\,t)v\|_2 \,\mathrm{d} \theta\\
&\leq \tau_{m+1,m}\,t\,\frac{1}{(p-1)!} \int_0^1 (1-\theta)^{p-1} \theta \, e_m^\ast \, \phif_1(\theta\,t\,T_m) \, e_1  \,\mathrm{d} \theta.
\end{align*}
Evaluation of the integral yields
\begin{equation}\label{partofproofphicor1}
\begin{aligned}
\| L_m^p(t)v \|_2
&\leq \tau_{m+1,m}\,t\,\frac{1}{(p-1)!} \int_0^1 (1-\theta)^{p-1} \theta \, e_m^\ast \, \phif_1(\theta\,t\,T_m) \, e_1  \,\mathrm{d} \theta\\
&= \tau_{m+1,m}\,t\,\sum_{k=0}^{\infty}\frac{e_m^\ast \,(\,t\,T_m)^k \, e_1}{(p-1)!\,(k+1)!} \int_0^1 (1-\theta)^{p-1} \theta^{k+1} \,     \,\mathrm{d} \theta \\
&= \tau_{m+1,m}\,t\,\sum_{k=0}^{\infty} \frac{e_m^\ast \,(\,t\,T_m)^k \, e_1}{(p+k+1)!}\\
&= \tau_{m+1,m}\,t\,e_m^\ast \phif_{p+1}(\,t\,T_m) \, e_1.
\end{aligned}
\end{equation}
This shows~\eqref{hermitianphiestimate1}.
To show~\eqref{hermitianphiestimate2} we start analogously to Theorem~\ref{theorem:asymerrorpricorrected}:
\begin{equation*}
\|L^{p,+}_m(t)v\|_2 = \|t\,\Opgen\,L^{p+1}_m(t)v\|_2 \leq \|\Opgen v_{m+1}\|_2\,\tau_{m+1,m} \,t\, \frac{1}{p!} \int_0^1 (1-\theta)^{p} \int_0^{\theta t}  |\delta_m( s)|\,\mathrm{d} s \,\mathrm{d} \theta.
\end{equation*}
Using $|\delta_m(s)|=\delta_m(s)$ and evaluating the inner integral by the $\phif_1$ function, we obtain
\begin{equation*}
\|L^{p,+}_m(t)v\|_2 \leq \|\Opgen v_{m+1}\|_2\,\tau_{m+1,m}\,t^2\,\frac{1}{p!} \int_0^1 (1-\theta)^{p} \theta \, e_m^\ast \, \phif_1(\theta\,t\,T_m) \, e_1  \,\mathrm{d} \theta.
\end{equation*}
Evaluation of the integral analogously to~\eqref{partofproofphicor1},
\begin{equation*}
\|L^{p,+}_m(t)v\|_2 \leq \|\Opgen v_{m+1}\|_2\,\tau_{m+1,m}\,t^2\,e_m^\ast \phif_{p+2}(\,t\,T_m) \, e_1,
\end{equation*}
completes the proof. \hfill\qed

