In~\cite{saad92s} it is stated that, typically,
the first term of the sum given in
Proposition~\ref{prop:saad92}, formula~\eqref{errorsaadterm1},
is already a good approximation to $L_m(t)v$.
Analogously to~\cite[Section 5.2]{saad92s}
we use the notation $\Erone$
for the norm of this term,
\begin{equation}\label{errorsaadterm1}\tag{$\Erone$}
\Erone = \tau_{m+1,m}\,t\,|e_m^\ast\phif_1(\sca\,t T_m)e_1|.
\end{equation}
In~\cite{chinesen17} it is even shown
that~$\Erone$ is an upper bound up
to a factor depending on spectral properties of the matrix $\Opgen$.
For the case of Hermitian $\sca\Opgen$ we show $\|L_m(t)v\|_2 \leq \Erone$ in Proposition~\ref{upperboundphi} below.

In Remark~\ref{rmk:PhiAsymptoticCorrect} below we show that $\Erone$ is also an asymptotically correct
approximation for the error norm
(in the sense of Proposition~\ref{prop:prop4}).
Furthermore, the error estimate $\Erone$ is computable at nearly no extra cost,
see~\cite[Proposition~2.1]{saad92s}.

According to~\cite[Proposition~2.1]{saad92s},
$\phif_1(\sca\,t T_m)$ can be computed from the extended matrix
\begin{subequations}
\begin{equation}\label{definetcor}
\Tcor_m =
\begin{bmatrix}
T_m&0\\
\tau_{m+1,m}\,e_m^\ast&0
\end{bmatrix}\in\mathbb C^{(m+1)\times (m+1)}
\end{equation}
as
\begin{equation}\label{computephi1}
{\rm e}^{\sca\,t\Tcor_m} e_1=
\begin{bmatrix}
{\rm e}^{\sca\,tT_m}e_1\\
\tau_{m+1,m}\,\sca\,t \,(e_m^\ast\,\phif_1(\sca\,t T_m)\,e_1)
\end{bmatrix}\in\mathbb C^{m+1}.
\end{equation}
\end{subequations}
Equation~\eqref{computephi1} can be used to evaluate the error estimate
$\Erone$
or a corrected Krylov approximation in the form
\begin{equation} \label{Smbar}
\Scor_m(t)v = \Vcor_m\,{\rm e}^{\sca\,t\Tcor_m}e_1
\text{~~~with~~~}
\Vcor_m=\Big[ V_m\,\big|\,v_{m+1} \Big] \in\mathbb C^{n\times (m+1)},
\end{equation}
for which the first term of the error expansion according to
Proposition~\ref{prop:saad92} vanishes, see~\cite{saad92s}.
For the error of the corrected Krylov approximation we use the notation
\begin{equation*}
L_m^+(t)v = E(t)v - \Scor_m(t)v.
\end{equation*}

For general $\phif$-functions we obtain an error representation similar to Proposition~\ref{prop:saad92} and
a corrected Krylov approximation for $\phif$-functions.
The corrected Krylov approximation to $\phif_p(\sca\,t\,\Opgen)v$ is given in~\cite[Theorem 2]{sidje98}:
\begin{equation*}
\phif_p(\sca\,t\,\Opgen)v \approx \Vcor_m \phif_p(\sca\,t\,\Tcor_m) e_1
\end{equation*}
with $\Tcor_m$ and $\Vcor_m$ given in~\eqref{definetcor} and~\eqref{Smbar}.
The error of the corrected Krylov approximation is denoted by
\begin{equation}\label{generalizeerrornotation2}
L^{p,+}_m(t)v = \phif_p(\sca\,t\,\Opgen)v - \Vcor_m \phif_p(\sca\,t\,\Tcor_m) e_1.
\end{equation}

The following remark will be used later on.
\begin{remark}\label{rmk:PhiAsymptoticCorrect}
From the representation~\eqref{defphiseries} for the $\phif_j$
together with~\eqref{eTe} and~\eqref{gammam} we observe
\begin{equation} \label{em-phi-e1}
\begin{aligned}
e_m^\ast \phif_j(\sca t T_m) e_1 &=

\frac{(\sca t)^{m-1} e_m^\ast T_m^{m-1}\,e_1}{(m-1+j)!}
+ \mathcal{O}(t^m)
= \gamma_m \,\frac{(\sca t)^{m-1}}{(m-1+j)!}
+ \mathcal{O}(t^m).
\end{aligned}
\end{equation}
By~\eqref{em-phi-e1} we observe $ e_m^\ast\phif_{j}(\sca\,tT_m)\,e_1 = \mathcal{O}(t^{m-1}) $ for $ j \geq 0 $
and we conclude that the asymptotically leading order term of $ L^p_m(t)v $ for $ t \to 0 $ is obtained by the leading term ($j=p+1$) of the series~\eqref{generalizeerrorSaadsum1}:
\begin{subequations}
\begin{equation}\label{Lpleadingtermsum}
L^p_m(t)v = \tau_{m+1,m} \sca\,t (e_m^\ast \phif_{p+1}(\sca\,t\,T_m) e_1 ) v_{m+1} + \mathcal{O}(t^m).
\end{equation}
Analogously we obtain the asymptotically leading order term of $ L^{p,+}_m(t)v $ for $ t \to 0 $ by the leading term ($j=p+2$) of the series~\eqref{generalizeerrorSaadsum2}:
\begin{equation}\label{Lpplusleadingtermsum}
L^{p,+}_m(t)v = \tau_{m+1,m} (\sca\,t)^2 (e_m^\ast \phif_{p+2}(\sca\,t\,T_m) e_1) \,\Opgen v_{m+1} + \mathcal{O}(t^{m+1}).
\end{equation}
\end{subequations}
The asymptotically leading terms in~\eqref{Lpleadingtermsum} and~\eqref{Lpplusleadingtermsum} can be used as error estimators:
\begin{subequations}
\begin{equation}\label{LPnextphierrorest}
\|L^p_m(t)v\|_2 \approx \tau_{m+1,m}\,t |e_m^\ast \phif_{p+1}(\sca\,t\,T_m) e_1|
\end{equation}
and
\begin{equation}\label{LPplusnextphierrorest}
\|L^{p,+}_m(t)v\|_2 \approx \|\Opgen v_{m+1}\|_2 \tau_{m+1,m}\,t^2 |e_m^\ast \phif_{p+2}(\sca\,t\,T_m) e_1|.
\end{equation}
\end{subequations}
The error estimators~\eqref{LPnextphierrorest} and~\eqref{LPplusnextphierrorest} are already suggested in \cite{sidje98,niewri12}.
We will refer to them as $\Erone$ in the context of the $\phif$-functions with standard and corrected Krylov approximation,
generalizing the corresponding quantities for the exponential case $p=0$.
\end{remark}

We also obtain \tjnew{true} upper bounds for the matrix exponential
($p=0$) and general $\phif$-functions with $p \geq 1$.

